2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"path/filepath"
10		"strings"
11	
12		"github.com/entireio/cli/cmd/entire/cli/interactive"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15		"github.com/entireio/cli/perf"
16		"github.com/spf13/cobra"
17	)
18	
19	type whyOptions struct {
20		Path string
21	}
22	
23	func newWhyCmd() *cobra.Command {
24		var opts whyOptions
25	
26		cmd := &cobra.Command{
27			Use:    "why [path]",
28			Short:  "Explain why a file looks the way it does",
29			Hidden: true,
30			Args:   cobra.MaximumNArgs(1),
31			RunE: func(cmd *cobra.Command, args []string) error {
32				if len(args) > 0 {
33					opts.Path = args[0]
34				}
35				if opts.Path != "" && !canRunWhyTUI(cmd.OutOrStdout()) {
36					cleanup := initWhyLogging(cmd.Context())
37					defer cleanup()
38				}
39				return runWhy(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), opts)
40			},
41		}
42	
43		return cmd
44	}
45	
46	func runWhy(ctx context.Context, w io.Writer, _ io.Writer, opts whyOptions) (err error) {
47		ctx, span := perf.Start(ctx, "why",
48			slog.String("path", opts.Path),
49			slog.Bool("has_path", opts.Path != ""))
50		defer func() {
51			span.RecordError(err)
52			span.End()
53		}()
54	
55		_, modeSpan := perf.Start(ctx, "detect_mode")
56		canUseTUI := canRunWhyTUI(w)
57		modeSpan.End()
58		if opts.Path == "" {
59			if !canUseTUI {
60				return errors.New("path required when not running interactively")
61			}
62			return errors.New("interactive file browser is not implemented yet")
63		}
64	
65		_, resolveSpan := perf.Start(ctx, "resolve_path")
66		repoRoot, gitPath, _, err := resolveWhyPath(ctx, opts.Path)
67		if err != nil {
68			resolveSpan.RecordError(err)
69			resolveSpan.End()
70			return err
71		}
72		resolveSpan.End()
73	
74		data, err := loadWhyViewData(ctx, repoRoot, gitPath)
75		if err != nil {
76			return err
77		}
78	
79		if canUseTUI {
80			_, renderSpan := perf.Start(ctx, "render_tui")
81			if err := runWhyTUI(ctx, w, data); err != nil {
82				renderSpan.RecordError(err)
83				renderSpan.End()
84				return err
85			}
86			renderSpan.End()
87			return nil
88		}
89	
90		_, renderSpan := perf.Start(ctx, "render_static")
91		content := renderWhyStatic(data)
92		renderSpan.End()
93	
94		_, outputSpan := perf.Start(ctx, "write_output")
95		outputExplainContent(w, content, false)
96		outputSpan.End()
97		return nil
98	}
99	
100	var canRunWhyTUI = defaultCanRunWhyTUI
101	
102	func defaultCanRunWhyTUI(w io.Writer) bool {
103		return !IsAccessibleMode() && interactive.IsTerminalWriter(w) && interactive.CanPromptInteractively()
104	}
105	
106	func initWhyLogging(ctx context.Context) func() {
107		if _, err := paths.WorktreeRoot(ctx); err != nil {
108			return func() {}
109		}
110		logging.SetLogLevelGetter(GetLogLevel)
111		if err := logging.Init(ctx, ""); err != nil {
112			return func() {}
113		}
114		return logging.Close
115	}
116	
117	func resolveWhyPath(ctx context.Context, input string) (string, string, string, error) {
118		repoRoot, err := paths.WorktreeRoot(ctx)
119		if err != nil {
120			return "", "", "", fmt.Errorf("not a git repository: %w", err)
121		}
122		repoRoot = normalizeWhyPathForRel(repoRoot)
123	
124		absPath := input
125		if !filepath.IsAbs(absPath) {
126			absPath, err = filepath.Abs(absPath)
127			if err != nil {
128				return "", "", "", fmt.Errorf("resolving path %q: %w", input, err)
129			}
130		}
131		absPath = normalizeWhyPathForRel(absPath)
132	
133		relPath, err := filepath.Rel(repoRoot, absPath)
134		if err != nil {
135			return "", "", "", fmt.Errorf("resolving path %q relative to repository: %w", input, err)
136		}
137		if relPath == "." || strings.HasPrefix(relPath, ".."+string(filepath.Separator)) || relPath == ".." {
138			return "", "", "", fmt.Errorf("path %q is outside the repository", input)
139		}
140	
141		return repoRoot, filepath.ToSlash(relPath), absPath, nil
142	}
143	
144	func normalizeWhyPathForRel(path string) string {
145		cleaned := filepath.Clean(path)
146		if resolved, err := filepath.EvalSymlinks(cleaned); err == nil {
147			return resolved
148		}
149		dir := filepath.Dir(cleaned)
150		base := filepath.Base(cleaned)
151		if resolvedDir, err := filepath.EvalSymlinks(dir); err == nil {
152			return filepath.Join(resolvedDir, base)
153		}
154		return cleaned
155	}
156	
157	func loadWhyViewData(ctx context.Context, repoRoot, gitPath string) (whyViewData, error) {
158		_, blameSpan := perf.Start(ctx, "git_blame")
159		blameOutput, err := runGitBlame(ctx, repoRoot, gitPath)
160		if err != nil {
161			blameSpan.RecordError(err)
162			blameSpan.End()
163			return whyViewData{}, err
164		}
165		blameSpan.End()
166	
167		_, parseSpan := perf.Start(ctx, "parse_blame")
168		lines, err := parseBlamePorcelain(blameOutput)
169		if err != nil {
170			parseSpan.RecordError(err)
171			parseSpan.End()
172			return whyViewData{}, fmt.Errorf("parse git blame output: %w", err)
173		}
174		parseSpan.End()
175	
176		_, buildRowsSpan := perf.Start(ctx, "build_rows")
177		blocks := collapseWhyBlameBlocks(lines)
178		rows := buildWhyBlameRows(lines, blocks)
179		buildRowsSpan.End()
180	
181		_, openRepoSpan := perf.Start(ctx, "open_repository")
182		repo, err := openRepository(ctx)
183		if err != nil {
184			openRepoSpan.RecordError(err)
185			openRepoSpan.End()
186			return whyViewData{}, fmt.Errorf("open repository: %w", err)
187		}
188		openRepoSpan.End()
189	
190		_, enrichSpan := perf.Start(ctx, "enrich_commits")
191		commits := enrichWhyCommits(ctx, repo, blocks)
192		enrichSpan.End()
193	
194		return whyViewData{
195			GitPath: gitPath,
196			Rows:    rows,
197			Blocks:  blocks,
198			Commits: commits,
199		}, nil
200	}
