43	func runGitBlame(ctx context.Context, repoRoot, gitPath string) ([]byte, error) {
44		cmd := exec.CommandContext(ctx, "git", "blame", "--line-porcelain", "--", gitPath)
45		cmd.Dir = repoRoot
46	
47		var stdout, stderr bytes.Buffer
48		cmd.Stdout = &stdout
49		cmd.Stderr = &stderr
50	
51		if err := cmd.Run(); err != nil {
52			details := strings.TrimSpace(stderr.String())
53			if details == "" {
54				return nil, fmt.Errorf("git blame failed for %s: %w", gitPath, err)
55			}
56			return nil, fmt.Errorf("git blame failed for %s: %w: %s", gitPath, err, details)
57		}
58	
59		return stdout.Bytes(), nil
60	}
61	
62	func parseBlamePorcelain(data []byte) ([]whyBlameLine, error) {
63		if len(data) == 0 {
64			return nil, nil
65		}
66	
67		rawLines := bytes.Split(bytes.TrimSuffix(data, []byte{'\n'}), []byte{'\n'})
68		metadataByCommit := make(map[string]whyBlameMetadata)
69		lines := make([]whyBlameLine, 0)
70	
71		var current *whyBlameLine
72		for lineNumber, raw := range rawLines {
73			line := strings.TrimSuffix(string(raw), "\r")
74	
75			if hash, originalLine, finalLine, ok, err := parseBlameHeader(line); err != nil {
76				return nil, fmt.Errorf("parse blame header on line %d: %w", lineNumber+1, err)
77			} else if ok {
78				if current != nil {
79					return nil, fmt.Errorf("blame record for %s:%d missing source line", current.CommitHash, current.FinalLine)
80				}
81				next := whyBlameLine{
82					CommitHash:   hash,
83					OriginalLine: originalLine,
84					FinalLine:    finalLine,
85				}
86				if metadata, exists := metadataByCommit[hash]; exists {
87					applyBlameMetadata(&next, metadata)
88				}
89				current = &next
90				continue
91			}
92	
93			if current == nil {
94				if strings.TrimSpace(line) == "" {
95					continue
96				}
97				return nil, fmt.Errorf("blame metadata without header on line %d", lineNumber+1)
98			}
99	
100			if strings.HasPrefix(line, "\t") {
101				current.Source = strings.TrimPrefix(line, "\t")
102				lines = append(lines, *current)
103				metadataByCommit[current.CommitHash] = metadataFromBlameLine(*current)
104				current = nil
105				continue
106			}
107	
108			if err := applyBlameMetadataLine(current, line); err != nil {
109				return nil, fmt.Errorf("parse blame metadata on line %d: %w", lineNumber+1, err)
110			}
111			metadataByCommit[current.CommitHash] = metadataFromBlameLine(*current)
112		}
113	
114		if current != nil {
115			return nil, fmt.Errorf("blame record for %s:%d missing source line", current.CommitHash, current.FinalLine)
116		}
117	
118		return lines, nil
119	}
120	
121	func parseBlameHeader(line string) (string, int, int, bool, error) {
122		fields := strings.Fields(line)
123		if len(fields) < 3 || !isBlameHash(fields[0]) {
124			return "", 0, 0, false, nil
125		}
126	
127		originalLine, err := strconv.Atoi(fields[1])
128		if err != nil {
129			return "", 0, 0, false, fmt.Errorf("invalid original line %q", fields[1])
130		}
131		finalLine, err := strconv.Atoi(fields[2])
132		if err != nil {
133			return "", 0, 0, false, fmt.Errorf("invalid final line %q", fields[2])
134		}
135	
136		return fields[0], originalLine, finalLine, true, nil
137	}
138	
139	func isBlameHash(value string) bool {
140		if len(value) < 7 {
141			return false
142		}
143		for _, r := range value {
144			if (r < '0' || r > '9') && (r < 'a' || r > 'f') && (r < 'A' || r > 'F') {
145				return false
146			}
147		}
148		return true
149	}
150	
151	func applyBlameMetadataLine(line *whyBlameLine, metadata string) error {
152		switch {
153		case strings.HasPrefix(metadata, "author "):
154			line.Author = strings.TrimPrefix(metadata, "author ")
155		case strings.HasPrefix(metadata, "author-time "):
156			raw := strings.TrimPrefix(metadata, "author-time ")
157			seconds, err := strconv.ParseInt(raw, 10, 64)
158			if err != nil {
159				return fmt.Errorf("invalid author-time %q", raw)
160			}
161			line.AuthorTime = time.Unix(seconds, 0)
162		case strings.HasPrefix(metadata, "filename "):
163			line.Filename = strings.TrimPrefix(metadata, "filename ")
164		}
165		return nil
166	}
167	
168	func metadataFromBlameLine(line whyBlameLine) whyBlameMetadata {
169		return whyBlameMetadata{
170			Author:     line.Author,
171			AuthorTime: line.AuthorTime,
172			Filename:   line.Filename,
173		}
174	}
175	
176	func applyBlameMetadata(line *whyBlameLine, metadata whyBlameMetadata) {
177		line.Author = metadata.Author
178		line.AuthorTime = metadata.AuthorTime
179		line.Filename = metadata.Filename
180	}
181	
182	func collapseWhyBlameBlocks(lines []whyBlameLine) []whyBlameBlock {
183		if len(lines) == 0 {
184			return nil
185		}
186	
187		blocks := make([]whyBlameBlock, 0)
188		current := whyBlameBlock{
189			CommitHash: lines[0].CommitHash,
190			StartLine:  lines[0].FinalLine,
191			EndLine:    lines[0].FinalLine,
192			StartRow:   0,
193			EndRow:     0,
194		}
195	
196		for i := 1; i < len(lines); i++ {
197			line := lines[i]
198			if line.CommitHash == current.CommitHash {
199				current.EndLine = line.FinalLine
200				current.EndRow = i
201				continue
202			}
203	
204			blocks = append(blocks, current)
205			current = whyBlameBlock{
206				CommitHash: line.CommitHash,
207				StartLine:  line.FinalLine,
208				EndLine:    line.FinalLine,
209				StartRow:   i,
210				EndRow:     i,
211			}
212		}
213	
214		blocks = append(blocks, current)
215		return blocks
216	}
217	
218	func buildWhyBlameRows(lines []whyBlameLine, blocks []whyBlameBlock) []whyBlameRow {
219		rows := make([]whyBlameRow, len(lines))
220		for i, line := range lines {
221			rows[i] = whyBlameRow{whyBlameLine: line}
222		}
223		for blockIndex, block := range blocks {
224			for rowIndex := block.StartRow; rowIndex <= block.EndRow && rowIndex < len(rows); rowIndex++ {
225				rows[rowIndex].BlockIndex = blockIndex
226			}
227		}
228		return rows
229	}
