94	func (m whyTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea interface
95		switch msg := msg.(type) {
96		case tea.WindowSizeMsg:
97			m.width = msg.Width
98			m.height = msg.Height
99			m.viewport.Width = msg.Width
100			m = m.refreshViewport()
101			return m, nil
102		case tea.KeyMsg:
103			return m.updateKey(msg)
104		}
105		return m, nil
106	}
