108	func (m whyTUIModel) updateKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
109		switch {
110		case key.Matches(msg, keys.Quit), key.Matches(msg, keys.Back):
111			return m, tea.Quit
112		case key.Matches(msg, keys.Up):
113			if m.selected > 0 {
114				m.selected--
115				m = m.ensureSelectedVisible()
116			}
117		case key.Matches(msg, keys.Down):
118			if m.selected < len(m.data.Rows)-1 {
119				m.selected++
120				m = m.ensureSelectedVisible()
121			}
122		case key.Matches(msg, keys.Home):
123			m.selected = 0
124			m.viewport.GotoTop()
125		case key.Matches(msg, keys.End):
126			if len(m.data.Rows) > 0 {
127				m.selected = len(m.data.Rows) - 1
128				m.viewport.GotoBottom()
129			}
130		case key.Matches(msg, keys.Confirm):
131			return m, nil
132		}
133		return m, nil
134	}
