136	func (m whyTUIModel) View() string {
137		if m.width == 0 {
138			return ""
139		}
140	
141		var b strings.Builder
142		b.WriteString(m.renderHeader())
143		b.WriteString(m.renderColumnHeader())
144		b.WriteString(m.renderViewport())
145		b.WriteString("\n")
146		b.WriteString(m.renderFooter())
147		return b.String()
148	}
