150	func (m whyTUIModel) renderViewport() string {
151		view := m.viewport.View()
152		selectedLine := m.selected - m.viewport.YOffset
153		if selectedLine < 0 || selectedLine >= m.viewport.Height {
154			return view
155		}
156	
157		lines := strings.Split(view, "\n")
158		if selectedLine >= len(lines) {
159			return view
160		}
161	
162		lines[selectedLine] = m.renderSelectedViewportLine(lines[selectedLine])
163		return strings.Join(lines, "\n")
164	}
