166	func (m whyTUIModel) renderSelectedViewportLine(line string) string {
167		line = markWhyTUISelectedLine(line)
168		if !m.styles.colorEnabled {
169			return line
170		}
171		line += strings.Repeat(" ", max(m.width-lipgloss.Width(line), 0))
172		return whyTUISelectedBackground + strings.ReplaceAll(line, whyTUIReset, whyTUIReset+whyTUISelectedBackground) + whyTUIReset
173	}
174	
175	func markWhyTUISelectedLine(line string) string {
176		if line == "" {
177			return ">"
178		}
179	
180		prefixLen := leadingSGRLen(line)
181		if prefixLen >= len(line) {
182			return line + ">"
183		}
184		if line[prefixLen] == ' ' {
185			return line[:prefixLen] + ">" + line[prefixLen+1:]
186		}
187		return line[:prefixLen] + ">" + line[prefixLen:]
188	}
189	
190	func leadingSGRLen(s string) int {
191		offset := 0
192		for offset < len(s) && s[offset] == '\x1b' {
193			if offset+1 >= len(s) || s[offset+1] != '[' {
194				break
195			}
196			end := strings.IndexByte(s[offset:], 'm')
197			if end < 0 {
198				break
199			}
200			offset += end + 1
201		}
202		return offset
203	}
