205	func (m whyTUIModel) refreshViewport() whyTUIModel {
206		m.lineWidth = whyLineColumnWidth(m.data.Rows)
207		headerHeight := strings.Count(m.renderHeader(), "\n") + strings.Count(m.renderColumnHeader(), "\n")
208		vpHeight := m.height - headerHeight - 1
209		if vpHeight < 1 {
210			vpHeight = 1
211		}
212	
213		if !m.ready {
214			m.viewport = viewport.New(m.width, vpHeight)
215			m.ready = true
216		} else {
217			m.viewport.Width = m.width
218			m.viewport.Height = vpHeight
219		}
220		m.viewport.SetContent(m.renderRows())
221		return m.ensureSelectedVisible()
222	}
