224	func (m whyTUIModel) ensureSelectedVisible() whyTUIModel {
225		if len(m.data.Rows) == 0 || m.viewport.Height <= 0 {
226			return m
227		}
228		if m.selected < m.viewport.YOffset {
229			m.viewport.SetYOffset(m.selected)
230			return m
231		}
232		bottom := m.viewport.YOffset + m.viewport.Height - 1
233		if m.selected > bottom {
234			m.viewport.SetYOffset(m.selected - m.viewport.Height + 1)
235		}
236		return m
237	}
