336	func (m whyTUIModel) renderFooter() string {
337		sep := m.styles.render(m.styles.helpSep, " · ")
338		fullHelp := m.styles.helpItem("↑/↓, j/k", "scroll") +
339			sep + m.styles.helpItem("home/end, g/G", "top/bottom") +
340			sep + m.styles.helpItem(keys.Quit.Help().Key, keys.Quit.Help().Desc)
341		standardHelp := m.styles.helpItem("↑/↓", "scroll") +
342			sep + m.styles.helpItem("home/end", "top/bottom") +
343			sep + m.styles.helpItem(keys.Quit.Help().Key, keys.Quit.Help().Desc)
344		shortHelp := m.styles.helpItem("↑/↓", "scroll")
345		quitHelp := m.styles.helpItem(keys.Quit.Help().Key, keys.Quit.Help().Desc)
346		helpChoices := []string{fullHelp, standardHelp, shortHelp, quitHelp}
347	
348		position := m.styles.render(m.styles.dim, m.positionText())
349		for _, help := range helpChoices {
350			gap := m.width - lipgloss.Width(help) - lipgloss.Width(position)
351			if gap >= 1 {
352				return help + strings.Repeat(" ", gap) + position
353			}
