1	package cli
2	
3	import (
4		"bytes"
5		"strings"
6	
7		"github.com/alecthomas/chroma/v2"
8		"github.com/alecthomas/chroma/v2/formatters"
9		"github.com/alecthomas/chroma/v2/lexers"
10		"github.com/alecthomas/chroma/v2/styles"
11		"github.com/charmbracelet/lipgloss"
12	)
13	
14	const whyHighlightStyleName = "github-dark"
15	
16	func highlightWhyCodeLines(filename string, lines []string, colorEnabled bool, maxWidth ...int) []string {
17		if len(lines) == 0 {
18			return nil
19		}
20		lines = expandWhyCodeTabs(lines)
21		width := whyHighlightMaxWidth(maxWidth)
22		plain := plainWhyCodeLines(lines, width)
23		if !colorEnabled {
24			return plain
25		}
26	
27		lexer := lexers.Match(filename)
28		if lexer == nil || lexer == lexers.Fallback {
29			return plain
30		}
31		lexer = chroma.Coalesce(lexer)
32	
33		iterator, err := lexer.Tokenise(nil, strings.Join(lines, "\n"))
34		if err != nil {
35			return plain
36		}
37	
38		tokenLines := chroma.SplitTokensIntoLines(iterator.Tokens())
39		highlighted := make([]string, len(lines))
40		copy(highlighted, plain)
41		for i := 0; i < len(lines) && i < len(tokenLines); i++ {
42			rendered, ok := renderWhyHighlightedTokenLine(tokenLines[i], width)
43			if !ok {
44				continue
45			}
46			highlighted[i] = rendered
47		}
48		return highlighted
49	}
50	
51	func expandWhyCodeTabs(lines []string) []string {
52		expanded := make([]string, len(lines))
53		for i, line := range lines {
54			expanded[i] = strings.ReplaceAll(line, "\t", "    ")
55		}
56		return expanded
57	}
58	
59	func whyHighlightMaxWidth(maxWidth []int) int {
60		if len(maxWidth) == 0 || maxWidth[0] <= 0 {
61			return 0
62		}
63		return maxWidth[0]
64	}
65	
66	func plainWhyCodeLines(lines []string, maxWidth int) []string {
67		plain := make([]string, len(lines))
68		for i, line := range lines {
69			if maxWidth > 0 {
70				line = truncateDisplayWidth(line, maxWidth, "")
71			}
72			plain[i] = line
73		}
74		return plain
75	}
76	
77	func renderWhyHighlightedTokenLine(tokens []chroma.Token, maxWidth int) (string, bool) {
78		if len(tokens) == 0 {
79			return "", true
80		}
81	
82		lineTokens := make([]chroma.Token, 0, len(tokens))
83		width := 0
84		for _, token := range tokens {
85			token.Value = strings.TrimSuffix(token.Value, "\n")
86			if token.Value == "" {
87				continue
88			}
89			if maxWidth > 0 {
90				remaining := maxWidth - width
91				if remaining <= 0 {
92					break
93				}
94				token.Value = truncateDisplayWidth(token.Value, remaining, "")
95				if token.Value == "" {
96					break
97				}
98				width += lipgloss.Width(token.Value)
99			}
100			lineTokens = append(lineTokens, token)
101		}
102		if len(lineTokens) == 0 {
103			return "", true
104		}
105	
106		var buf bytes.Buffer
107		if err := formatters.TTY16m.Format(&buf, whyHighlightStyle(), chroma.Literator(lineTokens...)); err != nil {
108			return "", false
109		}
110		return buf.String(), true
111	}
112	
113	func whyHighlightStyle() *chroma.Style {
114		style := styles.Get(whyHighlightStyleName)
115		if style == nil {
116			style = styles.Fallback
117		}
118		return style
119	}
